def place_fit(tr, lams=LAMP):
    return [(Vt.T@w, b) for w,b in ridge_path(Z[tr], 2.0*place[tr]-1, group_weights(g[tr]), lams)]
def bgshift(v, gg):
    mm = [v[gg==k].mean() for k in range(4)]; return 0.5*((mm[1]-mm[0])+(mm[3]-mm[2]))
def acc4(v, gg, yy): return np.array([((v[gg==k]>0)==(yy[gg==k]==1)).mean()*100 for k in range(4)])
def choose(m_tr, p_tr, g_tr, y_tr, rule):
    """m_tr original margins, p_tr inner-OOF place scores normalized to unit bg shift. returns (kappa, t, scale)"""
    if rule == 'P1':
        kap = bgshift(m_tr, g_tr)                      # zero the mean bg shift
        v = m_tr - kap*p_tr; ts = np.linspace(-5, 5, 201)
        w_ = [acc4(v-t, g_tr, y_tr).min() for t in ts]; best = np.max(w_); t = ts[np.where(np.array(w_)>=best-1e-9)[0]].mean()
        return kap, t, 1.0
    if rule == 'P2':
        best = (-1, -1, None)
        for kap in np.arange(5, 12.01, 0.5):
            v = m_tr - kap*p_tr
            for t in np.linspace(-5, 5, 101):
                a = acc4(v-t, g_tr, y_tr); mn = a@WTS
                if mn >= 95.5 and (a.min(), mn) > best[:2]: best = (a.min(), mn, (kap, t))
        return best[2][0], best[2][1], 1.0
    if rule == 'P3':
        F = np.c_[m_tr, p_tr]; clf = LogisticRegression(C=1e4, max_iter=5000).fit(F, y_tr, sample_weight=group_weights(g_tr))
        a = clf.coef_[0][0]; kap = -clf.coef_[0][1]/a; t = -clf.intercept_[0]/a
        return kap, t, a
def nested(rule, splits=SPL, R=R_, lam_rule='auc'):
    out = np.zeros((R, N)); K = len(splits)//R; chosen = []
    for i, (tr, te) in enumerate(splits):
